      svgRootDom.setAttribute("height", document.body.clientHeight - 348);
      svgRootDom.setAttribute(
        "viewBox",
        "" + g.x + " " + (g.y )+ " " + (g.width) + " " + (g.height) + ""
      );
    },
  },
};
